//////////////////////////////////////////////////////////////////
// classes and routines in LIB-02_TF_TABLE_1.C and LIB-02_TF_TABLE_2.C:

// The TF table is stored in ASCII format and contains the direct 
// thermodynamic functions, together with the charge state Q. 
// Each time FEOS is started, the TF table is read from the TF-table file 
// and tranformed into a HTable ( this process takes only microseconds ) 
// in order to obtain transparency of data and easy control.
// The class Htable contains matrices with the condensed information  
// about the thermodynamic functions.
class HTable{   
  public:
    double *ufield, *Tfield;
    double **Hfield,**H1field,**H2field,**H12field;
    double **Virial, **Nernst;
    double **Qfield;
    int    NU,NT;
    int    PrintFlag; 
    double TabMult_rho, TabMult_T;
    //
         HTable(char*, int );
    void generate3( char* );
    void write( char* );
    void read( char* );
    void kill( void );
  private:
};

// The class QIPscheme contains the QEOS interpolation scheme, with 
// which the data stored in the HTable are read and interpolated.
class QIPscheme {
  public:
    HTable ht;
    int    NU, NT;
    int    interested_in_Q;
    int    PrintFlag;
    double RhoMin, 
           *u_field, *t_field, 
           **H, **H1,
           **H2, **H12,
           r_scal, t_scal, p_scal,
           e_scal, s_scal, q_scal,
           pe_solid, dpedr_solid, Ee_solid;
    int    at_i, at_j;
    double **matextra_u0,
           **matextra_u_inf,
           **matextra_t0,
           **matextra_t_inf,    
           **matextra_u0t0,
           **matextra_uinftinf,
           **matextra_uinft0,
           **matextra_u0tinf;  
    //
           QIPscheme( char*, double, double, int );
           ~QIPscheme();
    void   getTFquantities( double, double, double*, double*, double*, double*, double* );
    void   Interpolate(double, double, double*, double*, double* );
    double getquantity( double, double, int );
  private:
    void Qextra_8cof( double*, double*, double*, double*,
			                double, double, double**, int );
    void Qextra_4cof( double*, double*, double*, double*,
			                double, double, double**, int ); 
    void Qextrapolate_t0( double*, double*, double*, double*,
				                  double, double, double,
				                  double, double,
				                  double*, double*, double* );
    void Qextrapolate_t_inf( double*, double*, double*, double*,
				                     double, double, double,
				                     double, double,
				                     double*, double*, double* );  
    void Qextrapolate_u0( double*, double*, double*, double*,
			                 	  double, double, double,
				                  double, double,
				                  double*, double*, double* );  
    void Qextrapolate_u_inf( double*, double*, double*, double*,
			                       double, double, double,
			                       double, double,
			                       double*, double*, double* );
    void Qextrapolate_u0t0( double*, double*, double*, double*,
				                    double, double,
				                    double, double,
				                    double*, double*, double* );
    void Qextrapolate_u0tinf( double*, double*, double*, double*,
				                      double, double,
				                      double, double,
				                      double*, double*, double* );
    void Qextrapolate_uinft0( double*, double*, double*, double*,
				                      double, double,
				                      double, double,
				                      double*, double*, double* );
    void Qextrapolate_uinftinf( double*, double*, double*, double*,
				                       double, double,
				                       double, double,
				                       double*, double*, double* );
    void Qbcucof( double*, double*, double*, double*, double, double, double** );
    void Qbcuint( double*, double*, double*, double*,
	                double, double, double, double,
	                double, double, double*, double*, double* ); 
    void bcucof( double*, double*, double*, double*, double, double, double** );
    void bcuint( double*, double*, double*, double*,
	               double, double, double, double,
	               double, double, double*, double*, double* );
}; 

